import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { SVGLoader } from 'three/addons/loaders/SVGLoader.js';
import { GUI } from 'three/addons/libs/lil-gui.module.min.js';
import { FontLoader } from 'three/examples/jsm/loaders/FontLoader.js';
import { TextGeometry } from 'three/examples/jsm/geometries/TextGeometry.js';
import { STLExporter } from 'three/examples/jsm/exporters/STLExporter.js';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';

import * as BufferGeometryUtils from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const name = 'ext-3d_switch';

/**
 * Helper: Create a rectangle shape representing a line with a given stroke width.
 * Given two points (assumed to be the first and last points of the line),
 * compute a rectangle that is centered on the line and extends half the stroke width
 * perpendicularly on both sides.
 */
function createLineShape(points, strokeWidth) {
  if (points.length < 2) return null;
  const p0 = points[0];
  const p1 = points[points.length - 1];
  const dx = p1.x - p0.x;
  const dy = p1.y - p0.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return null;
  // Perpendicular (normalized)
  const offset = new THREE.Vector2(-dy, dx).normalize().multiplyScalar(strokeWidth / 2);
  const shape = new THREE.Shape();
  shape.moveTo(p0.x + offset.x, p0.y + offset.y);
  shape.lineTo(p1.x + offset.x, p1.y + offset.y);
  shape.lineTo(p1.x - offset.x, p1.y - offset.y);
  shape.lineTo(p0.x - offset.x, p0.y - offset.y);
  shape.closePath();
  return shape;
}

/**
 * Helper: Given an SVG DOM node and its stroke width, create a compound shape
 * representing its stroke as a shape with a hole.
 */
function createStrokeCompoundShape(node, strokeW) {
  const tag = node.tagName.toLowerCase();
  if (tag === 'rect') {
    const x = parseFloat(node.getAttribute('x'));
    const y = parseFloat(node.getAttribute('y'));
    const width = parseFloat(node.getAttribute('width'));
    const height = parseFloat(node.getAttribute('height'));
    const outer = new THREE.Shape();
    outer.moveTo(x - strokeW/2, y - strokeW/2);
    outer.lineTo(x + width + strokeW/2, y - strokeW/2);
    outer.lineTo(x + width + strokeW/2, y + height + strokeW/2);
    outer.lineTo(x - strokeW/2, y + height + strokeW/2);
    outer.lineTo(x - strokeW/2, y - strokeW/2);
    const hole = new THREE.Path();
    hole.moveTo(x + strokeW/2, y + strokeW/2);
    hole.lineTo(x + width - strokeW/2, y + strokeW/2);
    hole.lineTo(x + width - strokeW/2, y + height - strokeW/2);
    hole.lineTo(x + strokeW/2, y + height - strokeW/2);
    hole.lineTo(x + strokeW/2, y + strokeW/2);
    outer.holes.push(hole);
    return outer;
  } else if (tag === 'circle') {
    const cx = parseFloat(node.getAttribute('cx'));
    const cy = parseFloat(node.getAttribute('cy'));
    const r = parseFloat(node.getAttribute('r'));
    const outerRadius = r + strokeW/2;
    const innerRadius = Math.max(r - strokeW/2, 0);
    const outer = new THREE.Shape();
    outer.absarc(cx, cy, outerRadius, 0, Math.PI * 2, false);
    const hole = new THREE.Path();
    hole.absarc(cx, cy, innerRadius, 0, Math.PI * 2, true);
    outer.holes.push(hole);
    return outer;
  } else if (tag === 'ellipse') {
    const cx = parseFloat(node.getAttribute('cx'));
    const cy = parseFloat(node.getAttribute('cy'));
    const rx = parseFloat(node.getAttribute('rx'));
    const ry = parseFloat(node.getAttribute('ry'));
    const outerRx = rx + strokeW/2;
    const outerRy = ry + strokeW/2;
    const innerRx = Math.max(rx - strokeW/2, 0);
    const innerRy = Math.max(ry - strokeW/2, 0);
    const outer = new THREE.Shape();
    outer.absellipse(cx, cy, outerRx, outerRy, 0, Math.PI * 2, false);
    const hole = new THREE.Path();
    hole.absellipse(cx, cy, innerRx, innerRy, 0, Math.PI * 2, true);
    outer.holes.push(hole);
    return outer;
  } else if (tag === 'polygon' || tag === 'polyline') {
    const pointsAttr = node.getAttribute('points');
    if (!pointsAttr) return null;
    const pts = pointsAttr.trim().split(/\s+/).map(pair => {
      const [x, y] = pair.split(',').map(parseFloat);
      return new THREE.Vector2(x, y);
    });
    if (pts.length < 3) return null;
    const outer = new THREE.Shape(pts);
    const centroid = pts.reduce((acc, p) => acc.add(p), new THREE.Vector2(0, 0))
                         .multiplyScalar(1 / pts.length);
    const dist = pts[0].distanceTo(centroid);
    const scale = (dist > strokeW/2) ? ((dist - strokeW/2) / dist) : 0;
    const innerPts = pts.map(p => new THREE.Vector2().subVectors(p, centroid)
                                  .multiplyScalar(scale).add(centroid));
    const hole = new THREE.Path(innerPts);
    outer.holes.push(hole);
    return outer;
  }
  return null;
}

/**
 * Preprocess the SVG string:
 *  - Convert <line> elements to <path> elements and mark them with a custom attribute.
 *  - Extract <text> elements for later conversion to 3D text.
 */
function preprocessSVG(svgString) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(svgString, 'image/svg+xml');

  // Convert <line> elements into <path> elements.
  const lines = doc.querySelectorAll('line');
  lines.forEach(line => {
    const x1 = line.getAttribute('x1');
    const y1 = line.getAttribute('y1');
    const x2 = line.getAttribute('x2');
    const y2 = line.getAttribute('y2');
    const d = `M ${x1} ${y1} L ${x2} ${y2}`;
    const path = doc.createElementNS("http://www.w3.org/2000/svg", "path");
    path.setAttribute('d', d);
    ['stroke', 'stroke-width', 'fill', 'opacity'].forEach(attr => {
      if (line.hasAttribute(attr)) {
        path.setAttribute(attr, line.getAttribute(attr));
      }
    });
    path.setAttribute('data-line', 'true');
    if (line.hasAttribute('stroke-width')) {
      path.setAttribute('data-stroke-width', line.getAttribute('stroke-width'));
    }
    line.parentNode.replaceChild(path, line);
  });

  // Extract <text> elements and remove them from the SVG.
  const texts = [];
  const textElems = doc.querySelectorAll('text');
  textElems.forEach(textElem => {
    const x = textElem.getAttribute('x') || "0";
    const y = textElem.getAttribute('y') || "0";
    const content = textElem.textContent;
    const fontSize = textElem.getAttribute('font-size') || "16";
    const fontFamily = textElem.getAttribute('font-family') || "Arial";
    const fill = textElem.getAttribute('fill') || "#000000";
    texts.push({
      x: parseFloat(x),
      y: parseFloat(y),
      content,
      fontSize: parseFloat(fontSize),
      fontFamily,
      fill
    });
    textElem.parentNode.removeChild(textElem);
  });

  return { svg: new XMLSerializer().serializeToString(doc), texts };
}

const loadExtensionTranslation = async function (svgEditor) {
  let translationModule;
  const lang = svgEditor.configObj.pref('lang');
  try {
    translationModule = await import(`./locale/${lang}.js`);
  } catch (_error) {
    console.warn(`Missing translation (${lang}) for ${name} - using 'en'`);
    translationModule = await import('./locale/en.js');
  }
  svgEditor.i18next.addResourceBundle(lang, name, translationModule.default);
};

export default {
  name,
  async init (_S) {
    const svgEditor = this;
    const { svgCanvas } = svgEditor;
    const { $id, $click } = svgCanvas;
    await loadExtensionTranslation(svgEditor);

    let scene = null; // Make scene accessible in wider scope

    // Function to save the 3D model
    const saveAs3DObject = (format) => {
      if (!scene || !$id('tool_3dView').pressed) return;

      let exporter;
      let mimeType;
      let extension;

      if (format === 'stl') {
        exporter = new STLExporter();
        mimeType = 'application/vnd.ms-pki.stl';
        extension = 'stl';
      } else {
        exporter = new OBJExporter();
        mimeType = 'text/plain';
        extension = 'obj';
      }

      const result = exporter.parse(scene);
      const blob = new Blob([result], { type: mimeType });
      const link = document.createElement('a');
      link.style.display = 'none';
      document.body.appendChild(link);
      link.href = URL.createObjectURL(blob);
      link.download = `model.${extension}`;
      link.click();
      document.body.removeChild(link);
    };

    // Click handlers for save buttons
    const clickSaveAsSTL = () => saveAs3DObject('stl');
    const clickSaveAsOBJ = () => saveAs3DObject('obj');

    // Toggle between 2D and 3D view.
    const clickLayerView = (e) => {
      $id('tool_3dView').pressed = !$id('tool_3dView').pressed;
      // Update save buttons state
      const saveButtons = document.querySelectorAll('.save3d');
      saveButtons.forEach(button => {
        button.style.opacity = $id('tool_3dView').pressed ? '1' : '0.3';
        button.style.pointerEvents = $id('tool_3dView').pressed ? 'auto' : 'none';
      });
      updateLayerView(e);
    };

    let extractedTexts = [];

    const updateLayerView = (e) => {
      const drawing = svgCanvas.getCurrentDrawing();
      let layer = drawing.getNumLayers();
      while (layer--) {
        if (!$id('tool_3dView').pressed) {
          const workarea = document.getElementById("workarea");
          if (workarea) {
            const extraCanvas = workarea.querySelector("canvas");
            if (extraCanvas) {
              extraCanvas.remove();
            }
            const svgCanvas = workarea.querySelector("#svgcanvas");
            if (svgCanvas) {
              svgCanvas.style.display = "block";
              document.querySelector('se-text[value="canvas"][text="tools.fit_to_canvas"]')?.click();
              document.querySelectorAll('.lil-gui.allow-touch-styles.root.autoPlace').forEach(el => el.remove());
            }
          }
        } else {
          let renderer, camera, gui, guiData;

          const render = () => {
            renderer.render(scene, camera);
          };

          const onWindowResize = () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            render();
          };

          const loadSVG = (url) => {
            scene = new THREE.Scene();
            scene.background = new THREE.Color(0xb0b0b0);

            const helper = new THREE.GridHelper(160, 10, 0x8d8d8d, 0xc1c1c1);
            helper.rotation.x = Math.PI / 2;
            scene.add(helper);

            const fullGroup = new THREE.Group();
            scene.add(fullGroup);

            const pathsGroup = new THREE.Group();
            fullGroup.add(pathsGroup);

            const loader = new SVGLoader();
            loader.load(url, function (data) {
              let renderOrder = 0;
              for (const path of data.paths) {
                if (path.userData.style.opacity !== undefined &&
                    parseFloat(path.userData.style.opacity) === 0) {
                  continue;
                }
                let effectiveFill = path.userData.style.fill;
                if (effectiveFill === 'none' && path.userData.style.stroke && path.userData.style.stroke !== 'none') {
                  effectiveFill = path.userData.style.stroke;
                }
                let isLine = false;
                if (path.userData.node && path.userData.node.getAttribute('data-line') === 'true') {
                  isLine = true;
                }

                // --- Updated strokeWidth retrieval using camelCase ---
                let strokeWidth = NaN;
                if (path.userData.node) {
                  const attrStrokeWidth = path.userData.node.getAttribute('stroke-width');
                  if (attrStrokeWidth !== null) {
                    strokeWidth = parseFloat(attrStrokeWidth);
                  }
                }
                if (isNaN(strokeWidth)) {
                  strokeWidth = parseFloat(path.userData.style.strokeWidth || 1);
                }
                if (isLine && path.userData.node) {
                  const swData = path.userData.node.getAttribute('data-stroke-width');
                  if (swData) strokeWidth = parseFloat(swData);
                }
                console.log(strokeWidth);
                // ----------------------------------

                if (guiData.drawFillShapes && effectiveFill !== undefined && effectiveFill !== 'none') {
                  const material = new THREE.MeshBasicMaterial({
                    color: new THREE.Color().setStyle(effectiveFill),
                    opacity: path.userData.style.fillOpacity,
                    transparent: true,
                    side: THREE.DoubleSide,
                    depthWrite: false,
                    wireframe: guiData.fillShapesWireframe
                  });
                  let shapes = [];
                  if (isLine && path.subPaths.length > 0) {
                    const points = path.subPaths[0].getPoints();
                    const lineShape = createLineShape(points, strokeWidth);
                    if (lineShape) shapes.push(lineShape);
                  } else {
                    shapes = SVGLoader.createShapes(path);
                  }
                  shapes.forEach(shape => {
                    const extrudeSettings = {
                      depth: guiData.depth,
                      bevelEnabled: true,
                      bevelThickness: 1,
                      bevelSize: 1,
                      bevelSegments: 2
                    };
                    const geometry = new THREE.ExtrudeGeometry(shape, extrudeSettings);
                    const mesh = new THREE.Mesh(geometry, material);
                    mesh.renderOrder = renderOrder++;
                    pathsGroup.add(mesh);
                  });
                }
                if (!isLine &&
                    guiData.drawStrokes &&
                    path.userData.style.stroke &&
                    path.userData.style.stroke !== 'none' &&
                    path.userData.style.fill !== 'none' &&
                    strokeWidth > 0) {
                  const material = new THREE.MeshBasicMaterial({
                    color: new THREE.Color().setStyle(path.userData.style.stroke),
                    opacity: path.userData.style.strokeOpacity,
                    transparent: true,
                    side: THREE.DoubleSide,
                    depthWrite: false,
                    wireframe: guiData.strokesWireframe
                  });
                  let compoundShape = null;
                  if (path.userData.node) {
                    const tag = path.userData.node.tagName.toLowerCase();
                    if (['rect', 'circle', 'ellipse', 'polygon', 'polyline'].includes(tag) ||
                        path.userData.node.hasAttribute('points')) {
                      compoundShape = createStrokeCompoundShape(path.userData.node, strokeWidth);
                    }
                  }
                  if (compoundShape) {
                    const extrudeSettings = {
                      depth: guiData.depth,
                      bevelEnabled: true,
                      bevelThickness: (strokeWidth / 10),
                      bevelSize: 1,
                      bevelSegments: 2
                    };
                    console.log(`dd: ${(strokeWidth / 10)}`);
                    const geometry = new THREE.ExtrudeGeometry(compoundShape, extrudeSettings);
                    const mesh = new THREE.Mesh(geometry, material);
                    mesh.renderOrder = renderOrder++;
                    pathsGroup.add(mesh);
                  } else {
                    for (const subPath of path.subPaths) {
                      const geometry = SVGLoader.pointsToStroke(subPath.getPoints(), path.userData.style);
                      if (geometry) {
                        const geometry2 = geometry.clone();
                        geometry2.translate(0, 0, guiData.depth);
                        const merged = BufferGeometryUtils.mergeGeometries([geometry, geometry2]);
                        const extrudedStroke = new THREE.Mesh(merged, material);
                        extrudedStroke.renderOrder = renderOrder++;
                        pathsGroup.add(extrudedStroke);
                      }
                    }
                  }
                }
              }

              const bboxPaths = new THREE.Box3().setFromObject(pathsGroup);
              const sizePaths = bboxPaths.getSize(new THREE.Vector3());
              const maxDimPaths = Math.max(sizePaths.x, sizePaths.y, sizePaths.z);
              const desiredSize = 80;
              const scaleFactor = (maxDimPaths > 0) ? (desiredSize / maxDimPaths) : 1;

              const centerPaths = bboxPaths.getCenter(new THREE.Vector3());
              pathsGroup.scale.set(scaleFactor, -scaleFactor, scaleFactor);
              pathsGroup.position.set(
                -centerPaths.x * scaleFactor,
                centerPaths.y * scaleFactor,
                -centerPaths.z * scaleFactor
              );

              if (extractedTexts.length > 0) {
                const fontLoader = new FontLoader();
                fontLoader.load('https://threejs.org/examples/fonts/helvetiker_regular.typeface.json', function (font) {
                  extractedTexts.forEach(txt => {
                    const geometry = new TextGeometry(txt.content, {
                      font: font,
                      size: txt.fontSize * scaleFactor,
                      depth: guiData.depth,
                      curveSegments: 12,
                      bevelEnabled: false
                    });
                    geometry.center();
                    const material = new THREE.MeshBasicMaterial({ color: txt.fill });
                    const mesh = new THREE.Mesh(geometry, material);
                    mesh.position.set(
                      txt.x * scaleFactor - centerPaths.x * scaleFactor,
                      -txt.y * scaleFactor + centerPaths.y * scaleFactor,
                      0
                    );
                    fullGroup.add(mesh);
                  });
                  const bboxFull = new THREE.Box3().setFromObject(fullGroup);
                  const centerFull = bboxFull.getCenter(new THREE.Vector3());
                  fullGroup.position.sub(centerFull);
                  render();
                });
              } else {
                const bboxFull = new THREE.Box3().setFromObject(fullGroup);
                const centerFull = bboxFull.getCenter(new THREE.Vector3());
                fullGroup.position.sub(centerFull);
                render();
              }
            });
          };

          const createGUI = () => {
            if (gui) gui.destroy();
            gui = new GUI();
            gui.add(guiData, 'drawStrokes').name('Draw strokes').onChange(update);
            gui.add(guiData, 'drawFillShapes').name('Draw fill shapes').onChange(update);
            gui.add(guiData, 'strokesWireframe').name('Wireframe strokes').onChange(update);
            gui.add(guiData, 'fillShapesWireframe').name('Wireframe fill shapes').onChange(update);
            gui.add(guiData, 'depth', 0, 50).name('Extrusion Depth').onChange(update);
            function update() {
              loadSVG(guiData.currentURL);
            }
          };

          camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 1, 1000);
          camera.position.set(0, 0, 200);

          renderer = new THREE.WebGLRenderer({ antialias: true });
          renderer.setPixelRatio(window.devicePixelRatio);
          renderer.setSize(window.innerWidth, window.innerHeight);

          const container = document.getElementById("workarea");
          const svgCanvas = container.querySelector("#svgcanvas");
          svgCanvas.style.display = "none";
          container.appendChild(renderer.domElement);

          const controls = new OrbitControls(camera, renderer.domElement);
          controls.addEventListener('change', render);
          controls.screenSpacePanning = true;
          window.addEventListener('resize', onWindowResize);

          let svgString = svgEditor.getSvgAsVariable();
          const processed = preprocessSVG(svgString);
          extractedTexts = processed.texts;
          const blob = new Blob([processed.svg], { type: 'image/svg+xml' });
          const svgUrl = URL.createObjectURL(blob);

          guiData = {
            currentURL: svgUrl,
            drawFillShapes: true,
            drawStrokes: true,
            fillShapesWireframe: false,
            strokesWireframe: false,
            depth: 10
          };

          loadSVG(guiData.currentURL);
          createGUI();
        }
      }
      $id('layerlist').querySelectorAll('tr.layer').forEach(function (el) {
        const layervis = el.querySelector('td.layervis');
        const vis = el.classList.contains('layersel') || !$id('tool_3dView').pressed ? 'layervis' : 'layerinvis layervis';
        layervis.setAttribute('class', vis);
      });
    };

    return {
      name: svgEditor.i18next.t(`${name}:name`),
      layersChanged () {
        if ($id('tool_3dView').pressed) {
          updateLayerView();
        }
        if (svgEditor.configObj.curConfig.layerView) {
          svgEditor.configObj.curConfig.layerView = false;
          $id('tool_3dView').pressed = true;
          updateLayerView();
        }
      },
      layerVisChanged () {
        if ($id('tool_3dView').pressed) {
          $id('tool_3dView').pressed = !$id('tool_3dView').pressed;
        }
      },
      callback () {
        const buttonTemplate = document.createElement('template');
        const title = `${name}:buttons.0.title`;
        const key = `${name}:buttons.0.key`;
        buttonTemplate.innerHTML = `
          <se-button id="tool_3dView" title="${title}" shortcut="${key}" src="3d_view.svg"></se-button>
          <se-button id="tool_save_stl" class="save3d" title="Save as STL" src="save.svg" style="opacity: 0.3; pointer-events: none;"></se-button>
          <se-button id="tool_save_obj" class="save3d" title="Save as OBJ" src="save.svg" style="opacity: 0.3; pointer-events: none;"></se-button>`;
        
        $id('editor_panel').append(buttonTemplate.content.cloneNode(true));
        $click($id('tool_3dView'), clickLayerView.bind(this));
        $click($id('tool_save_stl'), clickSaveAsSTL);
        $click($id('tool_save_obj'), clickSaveAsOBJ);
      }
    };
  }
};
